<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $proyectos = Illuminate\Support\Facades\DB::table("proyectos")->where("ejercicio_id", 17)->where("responsable_operativo_id", 443)->get(); foreach($proyectos as $p) { echo "Proyecto ID: $p->proyecto_id\n"; $actividades = Illuminate\Support\Facades\DB::table("actividades_sustantivas")->where("proyecto_id", $p->proyecto_id)->get(); foreach($actividades as $a) { echo "  Actividad ID: $a->id, Text: $a->descripcion\n"; $riesgos = Illuminate\Support\Facades\DB::table("actividad_riesgo")->join("riesgos", "actividad_riesgo.riesgo_id", "=", "riesgos.id")->where("actividad_riesgo.actividad_sustantiva_id", $a->id)->select("riesgos.local_id")->get(); echo "  Riesgos: " . $riesgos->count() . "\n"; foreach($riesgos as $r) echo "    $r->local_id\n"; } }
